const uint8_t* bytes = reinterpret_cast<const uint8_t*>(data);
for (size_t i = 0; i < n; ++i) {
    uint8_t byte = bytes[i];
    crc = crc32c_table[(crc ^ byte) & 0xff] ^ (crc >> 8);
}
return crc ^ 0xffffffffu;
